//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/DDR4_JEDEC_AXI.md
// ============================================================================
module DDR4_JEDEC_AXI_apb #(
  parameter int NDEV = 1,
  parameter int IDW = 4,
  parameter int ROWB = 16,
  parameter int COLB = 10,
  parameter int BGB = 1,
  parameter int BAB = 2,
  parameter int CL = 22,
  parameter int CWL = 16,
  parameter int T_RCD = 22,
  parameter int T_RP = 22,
  parameter int T_RAS = 52,
  parameter int T_RC = 74,
  parameter int T_RRD_S = 9,
  parameter int T_RRD_L = 11,
  parameter int T_FAW = 48,
  parameter int T_CCD_S = 4,
  parameter int T_CCD_L = 8,
  parameter int T_WTR_S = 4,
  parameter int T_WTR_L = 12,
  parameter int T_WR = 24,
  parameter int T_RTP = 12,
  parameter int T_RFC = 560,
  parameter int T_REFI = 12480,
  parameter int T_MRD = 8,
  parameter int T_MOD = 24,
  parameter int T_ZQINIT = 1024,
  parameter int T_XPR = 576,
  parameter int T_RESET = 64,
  parameter int T_CKE = 64,
  localparam int DQW = 16 * NDEV,
  localparam int BB = DQW
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [IDW-1:0] s_awid,
  input logic [31:0] s_awaddr,
  input logic [7:0] s_awlen,
  input logic [2:0] s_awsize,
  input logic [1:0] s_awburst,
  input logic s_awvalid,
  output logic s_awready,
  input logic [31:0] s_wdata,
  input logic [3:0] s_wstrb,
  input logic s_wlast,
  input logic s_wvalid,
  output logic s_wready,
  output logic [IDW-1:0] s_bid,
  output logic [1:0] s_bresp,
  output logic s_bvalid,
  input logic s_bready,
  input logic [IDW-1:0] s_arid,
  input logic [31:0] s_araddr,
  input logic [7:0] s_arlen,
  input logic [2:0] s_arsize,
  input logic [1:0] s_arburst,
  input logic s_arvalid,
  output logic s_arready,
  output logic [IDW-1:0] s_rid,
  output logic [31:0] s_rdata,
  output logic [1:0] s_rresp,
  output logic s_rlast,
  output logic s_rvalid,
  input logic s_rready,
  output logic p_reset_n,
  output logic p_cke,
  output logic p_odt,
  output logic p_cs_n,
  output logic p_act_n,
  output logic p_ras_n,
  output logic p_cas_n,
  output logic p_we_n,
  output logic [1:0] p_bg,
  output logic [1:0] p_ba,
  output logic [13:0] p_a,
  output logic p_wr,
  output logic [8*DQW-1:0] p_wdata,
  output logic [BB-1:0] p_wbe,
  input logic p_rvalid,
  input logic [8*DQW-1:0] p_rdata
);
  localparam logic [31:0] ID_VALUE = 32'h5D4A0001;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [11:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd12) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_init_done;
  logic [15:0]   c_n_rd;
  logic [15:0]   c_n_wr;
  logic [15:0]   c_n_err;
  logic [15:0]   c_n_act;
  logic [15:0]   c_n_hit;
  logic [15:0]   c_n_ref;
  logic          c_err_irq;
  DDR4_JEDEC_AXI_top #(.NDEV(NDEV), .IDW(IDW), .ROWB(ROWB), .COLB(COLB), .BGB(BGB), .BAB(BAB), .CL(CL), .CWL(CWL), .T_RCD(T_RCD), .T_RP(T_RP), .T_RAS(T_RAS), .T_RC(T_RC), .T_RRD_S(T_RRD_S), .T_RRD_L(T_RRD_L), .T_FAW(T_FAW), .T_CCD_S(T_CCD_S), .T_CCD_L(T_CCD_L), .T_WTR_S(T_WTR_S), .T_WTR_L(T_WTR_L), .T_WR(T_WR), .T_RTP(T_RTP), .T_RFC(T_RFC), .T_REFI(T_REFI), .T_MRD(T_MRD), .T_MOD(T_MOD), .T_ZQINIT(T_ZQINIT), .T_XPR(T_XPR), .T_RESET(T_RESET), .T_CKE(T_CKE)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .s_awid(s_awid),
    .s_awaddr(s_awaddr),
    .s_awlen(s_awlen),
    .s_awsize(s_awsize),
    .s_awburst(s_awburst),
    .s_awvalid(s_awvalid),
    .s_awready(s_awready),
    .s_wdata(s_wdata),
    .s_wstrb(s_wstrb),
    .s_wlast(s_wlast),
    .s_wvalid(s_wvalid),
    .s_wready(s_wready),
    .s_bid(s_bid),
    .s_bresp(s_bresp),
    .s_bvalid(s_bvalid),
    .s_bready(s_bready),
    .s_arid(s_arid),
    .s_araddr(s_araddr),
    .s_arlen(s_arlen),
    .s_arsize(s_arsize),
    .s_arburst(s_arburst),
    .s_arvalid(s_arvalid),
    .s_arready(s_arready),
    .s_rid(s_rid),
    .s_rdata(s_rdata),
    .s_rresp(s_rresp),
    .s_rlast(s_rlast),
    .s_rvalid(s_rvalid),
    .s_rready(s_rready),
    .p_reset_n(p_reset_n),
    .p_cke(p_cke),
    .p_odt(p_odt),
    .p_cs_n(p_cs_n),
    .p_act_n(p_act_n),
    .p_ras_n(p_ras_n),
    .p_cas_n(p_cas_n),
    .p_we_n(p_we_n),
    .p_bg(p_bg),
    .p_ba(p_ba),
    .p_a(p_a),
    .p_wr(p_wr),
    .p_wdata(p_wdata),
    .p_wbe(p_wbe),
    .p_rvalid(p_rvalid),
    .p_rdata(p_rdata),
    .init_done(c_init_done),
    .n_rd(c_n_rd),
    .n_wr(c_n_wr),
    .n_err(c_n_err),
    .n_act(c_n_act),
    .n_hit(c_n_hit),
    .n_ref(c_n_ref),
    .err_irq(c_err_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'({c_init_done});
      10'd6: apb_rdata = 32'({c_n_rd});
      10'd7: apb_rdata = 32'({c_n_wr});
      10'd8: apb_rdata = 32'({c_n_err});
      10'd9: apb_rdata = 32'({c_n_act});
      10'd10: apb_rdata = 32'({c_n_hit});
      10'd11: apb_rdata = 32'({c_n_ref});
      default: apb_rdata = '0;
